32	const LORA_ROUTE_BODY_LIMIT: usize = 128 * 1024 * 1024;
33	
34	#[derive(Clone)]
35	struct LoraRouteState {
36	    control: LoraClient,
37	    adapter_names: Arc<RwLock<HashSet<String>>>,
38	}
39	
40	#[derive(Clone)]
41	struct LoraOpenAiState {
42	    vllm_router: Router,
43	    base_model_name: String,
44	    served_model_names: Vec<String>,
45	    adapter_names: Arc<RwLock<HashSet<String>>>,
46	}
47	
48	#[derive(Debug, Deserialize)]
49	struct LoadLoraAdapterHttpRequest {
50	    lora_name: String,
51	    lora_path: PathBuf,
52	    #[serde(default)]
53	    load_inplace: bool,
54	    #[serde(default)]
55	    is_3d_lora_weight: bool,
56	}
