65	#[derive(Clone, Debug, Eq, PartialEq)]
66	pub struct LoraModule {
67	    name: String,
68	    path: PathBuf,
69	}
70	
71	/// CLI parser for `--lora-modules`: vLLM-style `name=path`, a JSON object,
72	/// or a single-entry JSON list with `name` and `path`.
73	pub fn parse_lora_modules_arg(value: &str) -> Result<LoraModule, String> {
74	    if let Some((name, path)) = value.split_once('=') {
75	        return parse_lora_module_fields(name, path);
76	    }
77	    let json: serde_json::Value =
78	        serde_json::from_str(value).map_err(|error| format!("invalid --lora-modules: {error}"))?;
79	    match json {
80	        serde_json::Value::Object(map) => parse_lora_module_json(&map),
81	        serde_json::Value::Array(entries) if entries.len() == 1 => {
82	            let Some(serde_json::Value::Object(map)) = entries.first() else {
83	                return Err("--lora-modules JSON list entries must be objects".to_string());
84	            };
85	            parse_lora_module_json(map)
86	        }
87	        serde_json::Value::Array(_) => Err(
88	            "pass multiple --lora-modules values instead of one JSON list with multiple entries"
89	                .to_string(),
90	        ),
91	        _ => Err(
92	            "--lora-modules must be `name=path`, a JSON object, or a single-entry JSON list"
93	                .to_string(),
94	        ),
95	    }
96	}
97	
98	fn parse_lora_module_json(
99	    map: &serde_json::Map<String, serde_json::Value>,
100	) -> Result<LoraModule, String> {
101	    let name = map
102	        .get("name")
103	        .and_then(serde_json::Value::as_str)
104	        .ok_or_else(|| "--lora-modules JSON object requires string field `name`".to_string())?;
105	    let path = map
106	        .get("path")
107	        .and_then(serde_json::Value::as_str)
108	        .ok_or_else(|| "--lora-modules JSON object requires string field `path`".to_string())?;
109	    parse_lora_module_fields(name, path)
110	}
111	
112	fn parse_lora_module_fields(name: &str, path: &str) -> Result<LoraModule, String> {
113	    if name.is_empty() {
114	        return Err("--lora-modules name must not be empty".to_string());
115	    }
116	    if path.is_empty() {
117	        return Err("--lora-modules path must not be empty".to_string());
118	    }
119	    Ok(LoraModule {
120	        name: name.to_string(),
121	        path: PathBuf::from(path),
122	    })
123	}
124	
125	#[derive(Debug, Serialize)]
126	struct ErrorBody {
127	    error: String,
128	}
