144	pub(crate) fn lora_routes(
145	    control: LoraClient,
146	    adapter_names: Arc<RwLock<HashSet<String>>>,
147	) -> Router {
148	    Router::new()
149	        .route("/v1/load_lora_adapter", post(load_lora_adapter))
150	        .route("/v1/unload_lora_adapter", post(unload_lora_adapter))
151	        .with_state(LoraRouteState {
152	            control,
153	            adapter_names,
154	        })
155	}
