157	pub(crate) fn lora_openai_routes(
158	    vllm_router: Router,
159	    base_model_name: String,
160	    served_model_names: Vec<String>,
161	    adapter_names: Arc<RwLock<HashSet<String>>>,
162	) -> Router {
163	    Router::new()
164	        .route("/v1/models", get(lora_models))
165	        .route("/v1/completions", post(forward_lora_openai_request))
166	        .route("/v1/chat/completions", post(forward_lora_openai_request))
167	        .with_state(LoraOpenAiState {
168	            vllm_router,
169	            base_model_name,
170	            served_model_names,
171	            adapter_names,
172	        })
173	}
174	
175	async fn load_lora_adapter(
176	    axum::extract::State(state): axum::extract::State<LoraRouteState>,
177	    Json(request): Json<LoadLoraAdapterHttpRequest>,
178	) -> Response {
179	    if request.lora_name.is_empty() {
180	        return bad_request("lora_name must not be empty");
181	    }
182	    if request.lora_path.as_os_str().is_empty() {
183	        return bad_request("lora_path must not be empty");
184	    }
185	    if request.is_3d_lora_weight {
186	        return bad_request("is_3d_lora_weight=true is not supported");
187	    }
188	
189	    let lora_name = request.lora_name.clone();
190	    match state
191	        .control
192	        .load(LoadLoraAdapterRequest {
193	            lora_name: request.lora_name,
194	            lora_path: request.lora_path,
195	            load_inplace: request.load_inplace,
196	        })
197	        .await
198	    {
199	        Ok(()) => {
200	            state.adapter_names.write().await.insert(lora_name.clone());
201	            (
202	                StatusCode::OK,
203	                format!("Success: LoRA adapter '{lora_name}' added successfully."),
204	            )
205	                .into_response()
206	        }
207	        Err(error @ LoraControlError::EngineGone) => (
208	            StatusCode::SERVICE_UNAVAILABLE,
209	            Json(ErrorBody {
210	                error: error.to_string(),
211	            }),
212	        )
213	            .into_response(),
214	        Err(LoraControlError::Failed(message)) => {
215	            (StatusCode::BAD_REQUEST, Json(ErrorBody { error: message })).into_response()
216	        }
217	    }
218	}
219	
220	async fn unload_lora_adapter(
221	    axum::extract::State(state): axum::extract::State<LoraRouteState>,
222	    Json(request): Json<UnloadLoraAdapterHttpRequest>,
223	) -> Response {
224	    if request.lora_name.is_empty() {
225	        return bad_request("lora_name must not be empty");
226	    }
227	
228	    let lora_name = request.lora_name.clone();
229	    match state
230	        .control
231	        .unload(UnloadLoraAdapterRequest {
232	            lora_name: request.lora_name,
233	            lora_int_id: request.lora_int_id,
234	        })
235	        .await
236	    {
237	        Ok(()) => {
238	            state.adapter_names.write().await.remove(&lora_name);
239	            (
240	                StatusCode::OK,
241	                format!("Success: LoRA adapter '{lora_name}' removed successfully."),
242	            )
243	                .into_response()
244	        }
245	        Err(error @ LoraControlError::EngineGone) => (
246	            StatusCode::SERVICE_UNAVAILABLE,
247	            Json(ErrorBody {
248	                error: error.to_string(),
249	            }),
250	        )
251	            .into_response(),
252	        Err(LoraControlError::Failed(message)) => {
253	            (StatusCode::BAD_REQUEST, Json(ErrorBody { error: message })).into_response()
254	        }
255	    }
256	}
257	
258	fn bad_request(message: impl Into<String>) -> Response {
259	    (
260	        StatusCode::BAD_REQUEST,
261	        Json(ErrorBody {
262	            error: message.into(),
263	        }),
264	    )
265	        .into_response()
266	}
