268	pub(crate) async fn load_startup_lora_modules(
269	    control: &LoraClient,
270	    adapter_names: &Arc<RwLock<HashSet<String>>>,
271	    lora_modules: &[LoraModule],
272	) -> Result<()> {
273	    for module in lora_modules {
274	        control
275	            .load(LoadLoraAdapterRequest {
276	                lora_name: module.name.clone(),
277	                lora_path: module.path.clone(),
278	                load_inplace: false,
279	            })
280	            .await
281	            .with_context(|| {
282	                format!(
283	                    "failed to load startup LoRA module {} from {}",
284	                    module.name,
285	                    module.path.display()
286	                )
287	            })?;
288	        adapter_names.write().await.insert(module.name.clone());
289	    }
290	    Ok(())
291	}
