16	pub(crate) fn prefill_only_routes(vllm_router: Router) -> Router {
17	    Router::new()
18	        .route("/v1/completions", post(validate_prefill_only))
19	        .route("/v1/chat/completions", post(validate_prefill_only))
20	        .with_state(vllm_router.clone())
