24	async fn validate_prefill_only(
25	    axum::extract::State(vllm_router): axum::extract::State<Router>,
26	    request: Request,
27	) -> Response {
28	    match validate_prefill_only_inner(vllm_router, request).await {
29	        Ok(response) => response,
30	        Err(error) => (
31	            StatusCode::BAD_REQUEST,
32	            Json(json!({
33	                "error": {
34	                    "message": format!("{error:#}"),
35	                    "type": "invalid_request_error",
36	                    "code": "invalid_request_error"
37	                }
38	            })),
39	        )
40	            .into_response(),
41	    }
42	}
43	
44	async fn validate_prefill_only_inner(
45	    vllm_router: Router,
46	    request: Request,
47	) -> anyhow::Result<Response> {
48	    let (mut parts, body) = request.into_parts();
49	    let body = to_bytes(body, REQUEST_BODY_LIMIT)
50	        .await
51	        .context("failed to read OpenAI request body")?;
52	    let value: serde_json::Value =
53	        serde_json::from_slice(&body).context("failed to parse OpenAI request JSON")?;
54	    let max_tokens = value.get("max_tokens").and_then(serde_json::Value::as_u64);
55	    let max_completion_tokens = value
56	        .get("max_completion_tokens")
57	        .and_then(serde_json::Value::as_u64);
58	    let is_chat = parts.uri.path() == "/v1/chat/completions";
59	    if is_chat
60	        && let (Some(max_tokens), Some(max_completion_tokens)) = (max_tokens, max_completion_tokens)
61	    {
62	        anyhow::ensure!(
63	            max_tokens == max_completion_tokens,
64	            "max_tokens ({max_tokens}) conflicts with max_completion_tokens \
65	             ({max_completion_tokens})"
66	        );
67	    }
68	    let effective_max_tokens = if is_chat {
69	        max_completion_tokens.or(max_tokens)
70	    } else {
71	        max_tokens
72	    };
73	    anyhow::ensure!(
74	        effective_max_tokens == Some(1),
75	        "prefill only routes require max_tokens=1, got {}",
76	        effective_max_tokens.map_or_else(|| "omitted".to_owned(), |value| value.to_string())
77	    );
78	    parts.headers.insert(
79	        axum::http::header::CONTENT_LENGTH,
80	        axum::http::HeaderValue::from_str(&body.len().to_string())
81	            .context("request body length is invalid")?,
82	    );
83	    vllm_router
84	        .oneshot(Request::from_parts(parts, Body::from(body)))
85	        .await
86	        .context("vLLM router failed to handle prefill-only request")
87	}
