175	async fn load_lora_adapter(
176	    axum::extract::State(state): axum::extract::State<LoraRouteState>,
177	    Json(request): Json<LoadLoraAdapterHttpRequest>,
178	) -> Response {
179	    if request.lora_name.is_empty() {
180	        return bad_request("lora_name must not be empty");
181	    }
182	    if request.lora_path.as_os_str().is_empty() {
183	        return bad_request("lora_path must not be empty");
184	    }
185	    if request.is_3d_lora_weight {
186	        return bad_request("is_3d_lora_weight=true is not supported");
187	    }
188	
189	    let lora_name = request.lora_name.clone();
190	    match state
191	        .control
192	        .load(LoadLoraAdapterRequest {
193	            lora_name: request.lora_name,
194	            lora_path: request.lora_path,
195	            load_inplace: request.load_inplace,
196	        })
197	        .await
198	    {
199	        Ok(()) => {
200	            state.adapter_names.write().await.insert(lora_name.clone());
201	            (
202	                StatusCode::OK,
203	                format!("Success: LoRA adapter '{lora_name}' added successfully."),
204	            )
205	                .into_response()
206	        }
207	        Err(error @ LoraControlError::EngineGone) => (
208	            StatusCode::SERVICE_UNAVAILABLE,
209	            Json(ErrorBody {
210	                error: error.to_string(),
211	            }),
212	        )
213	            .into_response(),
214	        Err(LoraControlError::Failed(message)) => {
215	            (StatusCode::BAD_REQUEST, Json(ErrorBody { error: message })).into_response()
216	        }
217	    }
218	}
