1	//! LoRA adapter control — an optional engine capability, deliberately
2	//! outside the scheduler contract.
3	//!
4	//! An engine that manages adapters mints the pair itself before spawning its
5	//! scheduler ([`LoraClient::channel`]), lets the scheduler capture the
6	//! receiver (drained inside `step`, applied when the batch is idle), and
7	//! returns the client on [`super::Engine::lora`]. The `Option` is the
8	//! capability: an engine without one cannot be asked, so no "unsupported"
9	//! error exists. The vocabulary lives here in the frontend layer — the
10	//! consumer of the client defines the words — keeping the frontend free of
11	//! model-crate types.
12	
13	use std::path::PathBuf;
14	
15	use tokio::sync::oneshot;
16	
17	#[derive(Clone, Debug, Eq, PartialEq)]
18	pub struct LoadLoraAdapterRequest {
19	    pub lora_name: String,
20	    pub lora_path: PathBuf,
21	    pub load_inplace: bool,
22	}
23	
24	#[derive(Clone, Debug, Eq, PartialEq)]
25	pub struct UnloadLoraAdapterRequest {
26	    pub lora_name: String,
27	    pub lora_int_id: Option<i64>,
28	}
29	
30	/// One command to the serving engine, carrying its reply slot. A dropped
31	/// reply (the engine tore down before applying) surfaces as
32	/// [`LoraControlError::EngineGone`] on the client.
33	pub enum LoraControl {
34	    Load {
35	        request: LoadLoraAdapterRequest,
36	        reply: oneshot::Sender<Result<(), String>>,
37	    },
38	    Unload {
39	        request: UnloadLoraAdapterRequest,
40	        reply: oneshot::Sender<Result<(), String>>,
41	    },
42	    List {
43	        reply: oneshot::Sender<Vec<String>>,
44	    },
45	}
46	
47	/// The engine's end: captured by the scheduler before spawn, drained inside
48	/// `step`.
49	pub type LoraControlReceiver = crossbeam_channel::Receiver<LoraControl>;
50	
51	#[derive(Debug, Eq, PartialEq, thiserror::Error)]
52	pub enum LoraControlError {
53	    /// The engine (or its reply) went away before answering.
54	    #[error("engine is gone")]
55	    EngineGone,
56	    #[error("LoRA control operation failed: {0}")]
57	    Failed(String),
58	}
59	
60	/// Async client for an engine's LoRA control channel. Rides
61	/// [`super::Engine::lora`] from launch to whoever serves the adapter routes.
62	#[derive(Clone)]
63	pub struct LoraClient {
64	    tx: crossbeam_channel::Sender<LoraControl>,
65	}
66	
67	impl LoraClient {
68	    /// Mint both ends of the channel.
69	    #[must_use]
70	    pub fn channel() -> (Self, LoraControlReceiver) {
71	        let (tx, rx) = crossbeam_channel::unbounded();
72	        (Self { tx }, rx)
73	    }
74	
75	    pub async fn load(&self, request: LoadLoraAdapterRequest) -> Result<(), LoraControlError> {
76	        let (reply, rx) = oneshot::channel();
77	        self.roundtrip(LoraControl::Load { request, reply }, rx)
78	            .await?
79	            .map_err(LoraControlError::Failed)
80	    }
81	
82	    pub async fn unload(&self, request: UnloadLoraAdapterRequest) -> Result<(), LoraControlError> {
83	        let (reply, rx) = oneshot::channel();
84	        self.roundtrip(LoraControl::Unload { request, reply }, rx)
85	            .await?
86	            .map_err(LoraControlError::Failed)
87	    }
88	
89	    pub async fn list(&self) -> Result<Vec<String>, LoraControlError> {
90	        let (reply, rx) = oneshot::channel();
91	        self.roundtrip(LoraControl::List { reply }, rx).await
92	    }
93	
94	    async fn roundtrip<T>(
95	        &self,
96	        control: LoraControl,
97	        rx: oneshot::Receiver<T>,
98	    ) -> Result<T, LoraControlError> {
99	        self.tx
100	            .send(control)
101	            .map_err(|_| LoraControlError::EngineGone)?;
102	        rx.await.map_err(|_| LoraControlError::EngineGone)
103	    }
104	}
